/**
 * Runs the Kotlin JVM tests, or explains precisely why it cannot.
 *
 * The tests themselves live in `android/src/test`, but there is no standalone Gradle build to
 * reach them from — `android/build.gradle` deliberately declares no AGP or Kotlin classpath,
 * because the library is only ever built as a subproject of a consuming app. The one consuming
 * app in this repository is `apps/example`, whose `android/` directory is generated by
 * `expo prebuild` and is not committed. So the tests need two things a fresh clone does not
 * have: that generated project, and an Android SDK.
 *
 * That is why `npm run verify` used to skip them, and why twelve test files covering the
 * recycling contract, the host-row ownership guard and the keyboard path only ran when someone
 * remembered `npm run test:kotlin`. This script is the compromise that lets `verify` call them
 * anyway:
 *
 * - **Prerequisites present** — run them. Anyone who has done `npm run android` once is here.
 * - **Prerequisites missing** — say so loudly, name the exact command that fixes it, exit 0.
 *   `verify` on a machine with only Node and Xcode keeps working, which was the whole of the
 *   original objection.
 * - **`--require`** — exit non-zero instead of skipping. CI passes this, so "skipped" can never
 *   be mistaken for "passed" in the one place that decides whether a release is green.
 *
 *   node scripts/run-kotlin-tests.mjs [--require] [-- <extra gradle args>]
 */
import { spawnSync } from 'node:child_process'
import { existsSync, readFileSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const here = path.dirname(fileURLToPath(import.meta.url))
const repoRoot = path.join(here, '..', '..', '..')
const androidDir = path.join(repoRoot, 'apps', 'example', 'android')
const gradlew = path.join(androidDir, 'gradlew')

/** The Gradle path autolinking gives this package inside the example app. */
const MODULE = ':rngui_collection-view'

const argv = process.argv.slice(2)
const required = argv.includes('--require')
const gradleArgs = argv.filter((arg) => arg !== '--require')

/**
 * Gradle finds the SDK through `local.properties` or the environment, in that order. Checking
 * both here rather than letting Gradle fail turns a wall of daemon output into one line.
 */
function hasAndroidSdk() {
  const localProperties = path.join(androidDir, 'local.properties')
  if (
    existsSync(localProperties) &&
    /^\s*sdk\.dir\s*=/m.test(readFileSync(localProperties, 'utf8'))
  ) {
    return true
  }
  return Boolean(process.env.ANDROID_HOME || process.env.ANDROID_SDK_ROOT)
}

function unavailable(reason, remedy) {
  if (required) {
    console.error(`\nKotlin tests could not run: ${reason}\n\n  ${remedy}\n`)
    process.exit(1)
  }
  console.warn(
    `\n⚠️  Skipping the Kotlin tests: ${reason}\n` +
      `   They are not being run, and nothing below covers them.\n\n` +
      `   To run them:  ${remedy}\n`
  )
  process.exit(0)
}

if (!existsSync(gradlew)) {
  unavailable(
    'apps/example/android does not exist yet',
    'npm run prebuild   # then re-run npm run verify'
  )
}

if (!hasAndroidSdk()) {
  unavailable(
    'no Android SDK found (no sdk.dir in local.properties, no ANDROID_HOME)',
    'export ANDROID_HOME=$HOME/Library/Android/sdk'
  )
}

const result = spawnSync(gradlew, [`${MODULE}:test`, ...gradleArgs], {
  cwd: androidDir,
  stdio: 'inherit',
})

if (result.error) {
  console.error(`\nCould not start Gradle: ${result.error.message}\n`)
  process.exit(1)
}

process.exit(result.status ?? 1)
